/**
 * UUID used to correlate one authenticated UCP protocol request.
 */
export type UcpRequestIdParameter = string;

/**
 * Declares the HTTPS profile whose Ed25519 key authenticates this request.
 */
export type UcpAgentParameter = string;

/**
 * Unix timestamp in seconds, accepted within five minutes. The external agent profile must publish ucp.authentication with type ed25519, a key_id, and an Ed25519 public_key_jwk.
 */
export type UcpAgentTimestampParameter = string;

/**
 * Base64url Ed25519 signature over method, request target, profile URL, key ID, timestamp, nonce, Idempotency-Key, and SHA-256 body digest, separated by newlines.
 */
export type UcpAgentSignatureParameter = string;

/**
 * A unique request nonce. Reuse is rejected, including during the five-minute signature window.
 */
export type UcpAgentNonceParameter = string;

